import { ArrowUpRight, BookOpen, Check, ChevronDown, HelpCircle, Link2, LogOut, MessageSquare, Plus, Settings, X } from 'lucide-react';
import type { Conversation } from '../../../packages/contracts/src/index';
import type { useSidebar } from './useSidebar';

type Props = {
  navigation: ReturnType<typeof useSidebar>;
  conversations: Conversation[];
  currentId?: string;
  petConversation: string | null;
  ownerName: string;
  development: boolean;
  docsUrl: string;
