import { useEffect, useRef, useState } from 'react';
import { ArrowUpRight, BookOpen, LogOut, Settings } from 'lucide-react';

type Props = { name: string; development: boolean; docsUrl: string; onSettings: () => void; onLogout: () => void };

export function AccountMenu({ name, development, docsUrl, onSettings, onLogout }: Props) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const initialItem = useRef(0);
  function close(restore = true) { setOpen(false); if (restore) trigger.current?.focus(); }
  useEffect(() => {
    if (!open) return;
    const items = menu.current?.querySelectorAll<HTMLElement>('[role="menuitem"]');
    items?.[initialItem.current < 0 ? items.length - 1 : 0]?.focus();
    const outside = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false); };
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [open]);
  return <div className="account-menu" ref={root} onBlur={event => {
    if (!event.currentTarget.contains(event.relatedTarget as Node)) setOpen(false);
  }}>
    <button className="account-menu-trigger" ref={trigger} aria-label="Account menu" title={name}
      aria-haspopup="menu" aria-expanded={open} aria-controls={open ? 'account-menu-items' : undefined}
      onClick={() => { initialItem.current = 0; setOpen(!open); }}
      onKeyDown={event => {
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
          event.preventDefault(); initialItem.current = event.key === 'ArrowUp' ? -1 : 0; setOpen(true);
        }
      }}><span className="account-avatar" aria-hidden="true">{name.charAt(0).toUpperCase()}</span></button>
    {open && <div className="account-menu-content" id="account-menu-items" role="menu" aria-label="Account" ref={menu}
      onKeyDown={event => {
        const items = [...event.currentTarget.querySelectorAll<HTMLElement>('[role="menuitem"]')];
        const current = items.indexOf(document.activeElement as HTMLElement);
        if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
          event.preventDefault();
          const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (current + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
          items[next]?.focus();
        } else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
        else if (event.key === 'Tab') close();
      }}>
      <div className="account-menu-heading" role="presentation"><strong>{name}</strong><span>{development ? 'Local preview' : 'Personal workspace'}</span></div>
      <a role="menuitem" tabIndex={-1} href={docsUrl} target="_blank" rel="noreferrer" onClick={() => close()}><BookOpen size={16}/>Build documentation<ArrowUpRight className="account-external" size={14}/></a>
      <button role="menuitem" tabIndex={-1} aria-label="Open settings" onClick={() => { close(); onSettings(); }}><Settings size={16}/>Settings</button>
      <div className="account-menu-separator" role="separator"/>
      <button role="menuitem" tabIndex={-1} onClick={() => { close(); onLogout(); }}><LogOut size={16}/>Logout</button>
    </div>}
  </div>;
}
